tool_input.command:
cat > test/totals.test.js << 'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';

test('lineTotal with basic values', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal with qty 1', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work', qty: 1, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 8500);
});

test('lineTotal with large quantity', () => {
  const line = { sku: 'LOGO-PACK', name: 'Logo package', qty: 100, unitPrice: 120000, vatRate: 21 };
  assert.equal(lineTotal(line), 12000000);
});

test('lineTotal returns integer', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21 };
  const result = lineTotal(line);
  assert(Number.isInteger(result));
});

test('invoiceTotals with single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8479);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 48854);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
      { sku: 'ICON-SET', name: 'Icon set', qty: 2, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DES-HOUR: 42500 - 2125 = 40375, VAT 8479
  // ICON-SET: 1960 - 0 = 1960, VAT 412
  assert.equal(totals.subtotal, 44460);
  assert.equal(totals.discount, 2125);
  assert.equal(totals.vat, 8891);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals with zero discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 8925);
});

test('invoiceTotals with 100% discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 100 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.discount, 42500);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with VAT-free items', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'WORKSHOP-DAY', name: 'Workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 60000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 60000);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer', qty: 10, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Workshop', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DES-HOUR: 8500, VAT 1785
  // PRINT-A4: 370, VAT 33
  // WORKSHOP-DAY: 60000, VAT 0
  assert.equal(totals.subtotal, 68870);
  assert.equal(totals.vat, 1818);
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
    voucher: { code: 'SAVE10', amount: 5000 },
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.vat, 8925);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 46425);
});

test('invoiceTotals without voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals clamps negative total to 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set', qty: 1, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
    voucher: { code: 'FREE', amount: 5000 },
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with empty lines returns zero totals', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns all fields', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(totals.hasOwnProperty('subtotal'));
  assert(totals.hasOwnProperty('discount'));
  assert(totals.hasOwnProperty('vat'));
  assert(totals.hasOwnProperty('voucher'));
  assert(totals.hasOwnProperty('total'));
  assert.equal(Object.keys(totals).length, 5);
});

test('invoiceTotals with complex discount and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 10, unitPrice: 8500, vatRate: 21, discountPercent: 12.5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line: 85000, discount 10625, after 74375, VAT 15619
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 10625);
  assert.equal(totals.vat, 15619);
});

test('invoiceTotals returns integer values', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(Number.isInteger(totals.subtotal));
  assert(Number.isInteger(totals.discount));
  assert(Number.isInteger(totals.vat));
  assert(Number.isInteger(totals.voucher));
  assert(Number.isInteger(totals.total));
});

test('invoiceTotals with large values', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'BRAND-BOOK', name: 'Brand book', qty: 10, unitPrice: 245000, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2450000);
  assert(totals.vat > 0);
  assert.equal(totals.total, 2450000 + totals.vat);
});
EOF
